\begin{restatable}{theorem}{thmCountingSparseSubgraphs}
    \label{thm:countingSparseSubgraphs}
    Let $G=(V,E)$ be a $d$-regular graph.
    There exists a constant $c$ such that for any $k \geq c \log^9(n)$ the number of subsets $J\subseteq V$ such that $G[J]$ has edge density at most $\frac{1}{k}\frac{d}{n}$ is at most \[2^{\frac{n}{2}\left(1+O\left(\frac{\log^3n}{d}\right)+O\left(\frac{\log^{3}n}{k^{1/3}}\right)\right)}.\]
